package com.ecole.gestion_scolaire.transport.entity;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="transport_route") public class TransportRoute { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(name="school_year_id") public Long schoolYearId; @Column(name="campus_id") public Long campusId; public String code; public String name; @Column(name="route_type") public String routeType="SCHOOL"; public String description; public String status="ACTIVE"; @Column(name="vehicle_id") public Long vehicleId; @Column(name="driver_id") public Long driverId; @Column(name="morning_departure") public LocalTime morningDeparture; @Column(name="return_departure") public LocalTime returnDeparture; public boolean active=true; public String notes; @Column(name="created_at") public OffsetDateTime createdAt; @Column(name="updated_at") public OffsetDateTime updatedAt; @PrePersist void p(){var n=OffsetDateTime.now();createdAt=n;updatedAt=n;if(routeType==null)routeType="SCHOOL";if(status==null)status="ACTIVE";} @PreUpdate void u(){updatedAt=OffsetDateTime.now();} }
